// ========================================
// DEBUG: EMBEDDING VALIDATION NODE
// ========================================
// Dieser Node validiert Embeddings VOR dem Pinecone-Upload
// und zeigt detaillierte Informationen zur Fehlersuche

const EXPECTED_DIMENSION = 768; // text-embedding-004
const EMBEDDING_CONNECTION = 'ai_embedding';

// Input holen
const input = $input.all();

console.log('\n========================================');
console.log('🔍 EMBEDDING VALIDATION STARTED');
console.log('========================================');
console.log(`Total Items: ${input.length}`);

// Prüfe ob Input existiert
if (input.length === 0) {
  console.error('❌ FEHLER: Keine Input-Items vorhanden!');
  throw new Error('Keine Embeddings zum Validieren vorhanden');
}

// Prüfe jedes Item
const results = [];
let hasErrors = false;

for (let i = 0; i < input.length; i++) {
  const item = input[i];
  console.log(`\n--- Item ${i + 1}/${input.length} ---`);

  // 1. Prüfe JSON-Daten
  const json = item.json || {};
  console.log(`JSON Keys: ${Object.keys(json).join(', ')}`);

  // 2. Prüfe ob Embedding vorhanden ist
  const embedding = json.embedding || json.vector || json.embeddings;

  if (!embedding) {
    console.error('❌ FEHLER: Kein Embedding gefunden!');
    console.log('Verfügbare Keys:', Object.keys(json));
    hasErrors = true;

    results.push({
      json: {
        item_index: i,
        status: 'ERROR',
        error: 'Kein Embedding gefunden',
        available_keys: Object.keys(json),
        raw_data: JSON.stringify(json).substring(0, 500)
      }
    });
    continue;
  }

  // 3. Prüfe ob Embedding ein Array ist
  if (!Array.isArray(embedding)) {
    console.error('❌ FEHLER: Embedding ist kein Array!');
    console.log('Embedding Type:', typeof embedding);
    hasErrors = true;

    results.push({
      json: {
        item_index: i,
        status: 'ERROR',
        error: 'Embedding ist kein Array',
        embedding_type: typeof embedding,
        embedding_value: JSON.stringify(embedding).substring(0, 200)
      }
    });
    continue;
  }

  // 4. Prüfe Dimension
  const dimension = embedding.length;
  console.log(`Embedding Dimension: ${dimension}`);

  if (dimension === 0) {
    console.error('❌ FEHLER: Embedding hat Dimension 0!');
    console.error('Dies bedeutet: API hat leeres Array zurückgegeben');
    console.error('Mögliche Ursachen:');
    console.error('  - Gemini API Key ungültig');
    console.error('  - Rate Limiting');
    console.error('  - Input-Text ist leer');
    console.error('  - Embedding-Node falsch konfiguriert');
    hasErrors = true;

    results.push({
      json: {
        item_index: i,
        status: 'ERROR',
        error: 'Embedding Dimension ist 0',
        embedding_array: JSON.stringify(embedding),
        text_preview: (json.pageContent || json.text || '').substring(0, 200)
      }
    });
    continue;
  }

  if (dimension !== EXPECTED_DIMENSION) {
    console.warn(`⚠️ WARNUNG: Dimension ${dimension} ≠ ${EXPECTED_DIMENSION}`);
    console.warn('Pinecone Index erwartet möglicherweise andere Dimension!');
  }

  // 5. Prüfe ob Werte numerisch sind
  const nonNumericValues = embedding.filter(v => typeof v !== 'number');
  if (nonNumericValues.length > 0) {
    console.error('❌ FEHLER: Embedding enthält nicht-numerische Werte!');
    console.error('Erste nicht-numerische Werte:', nonNumericValues.slice(0, 5));
    hasErrors = true;

    results.push({
      json: {
        item_index: i,
        status: 'ERROR',
        error: 'Embedding enthält nicht-numerische Werte',
        non_numeric_count: nonNumericValues.length,
        examples: nonNumericValues.slice(0, 5)
      }
    });
    continue;
  }

  // 6. Prüfe ob Werte im vernünftigen Bereich sind
  const min = Math.min(...embedding);
  const max = Math.max(...embedding);
  console.log(`Value Range: [${min.toFixed(4)}, ${max.toFixed(4)}]`);

  if (Math.abs(max) > 10 || Math.abs(min) > 10) {
    console.warn('⚠️ WARNUNG: Embedding-Werte ungewöhnlich groß');
    console.warn('Normalerweise: [-1, 1] oder [-0.5, 0.5]');
  }

  // 7. SUCCESS!
  console.log('✅ Embedding ist VALIDE');
  console.log(`First 5 values: [${embedding.slice(0, 5).map(v => v.toFixed(4)).join(', ')}...]`);

  results.push({
    json: {
      ...json,
      validation_status: 'OK',
      validation_dimension: dimension,
      validation_min: min,
      validation_max: max
    }
  });
}

console.log('\n========================================');
if (hasErrors) {
  console.error('❌ VALIDATION FAILED - Fehler gefunden!');
  console.error('Prüfe die Logs oben für Details');
  throw new Error('Embedding Validation fehlgeschlagen - siehe Logs');
} else {
  console.log('✅ VALIDATION SUCCESSFUL');
  console.log(`Alle ${results.length} Embeddings sind valide`);
}
console.log('========================================\n');

return results;
